package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.service.jobs.GenerationFlowService.Stage;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.*;
import tools.jackson.databind.json.JsonMapper;

/** No real provider calls. Proof references and observations are unmistakably fictional. */
class CatalogDedupV2RequestTest {
    ObjectNode snapshot(Stage stage,Boolean changed){var root=GenerationRequestBuilderTest.snapshot(stage);root.set(FrozenApplicationContext.FIELD,new CatalogDedupResultV2Test().context(stage,changed));return root;}
    ObjectNode request(ObjectNode root,Stage stage){return (ObjectNode)CanonicalJson.parse(GenerationRequestBuilderTest.build(root,stage));}
    @Test void FourCatalogRequestsUseOriginalV2ContractClosureAndExactCanonicalInput()throws Exception{var schemas=CanonicalJson.parse(Files.readAllBytes(Path.of("../contracts/catalog-dedup-result-v2.schema.json")));try(var stream=GenerationRequestBuilder.class.getResourceAsStream("/contracts/schemas.json")){assertNotNull(stream);assertArrayEquals(Files.readAllBytes(Path.of("../contracts/schemas.json")),stream.readAllBytes());}for(var stage:List.of(Stage.AGENT_DEDUP,Stage.SKILL_DEDUP,Stage.WORKFLOW_DEDUP,Stage.MODEL_DEDUP)){var root=snapshot(stage,true);var req=request(root,stage);assertEquals("site-catalog-dedup-v2",req.get("prompt_version").asText());assertEquals("#/$defs/CatalogDedupResultV2",req.get("json_schema").get("$ref").asText());var defs=req.get("json_schema").get("$defs");assertEquals(3,defs.size());for(var field:defs.properties())assertEquals(schemas.get("$defs").get(field.getKey()),field.getValue());GenerationRequestBuilderTest.checkRefs(req.get("json_schema"),defs);assertArrayEquals(CanonicalJson.bytes(root),req.get("messages").get(1).get("content").asText().getBytes(StandardCharsets.UTF_8));String system=req.get("messages").get(0).get("content").asText();assertTrue(system.contains("catalog_version_qualifications"));var example=CanonicalJson.parse(system.substring(system.lastIndexOf("格式示例（只示范结构）：\n")+"格式示例（只示范结构）：\n".length()));var input=FrozenApplicationContext.fromJson(root.get(FrozenApplicationContext.FIELD)).input("fictional-root","fictional-attempt",req.get("input_hash").asText(),0);assertEquals("dedup",ResultApplicationService.validate(input,ResultApplicationService.providerEnvelope(input,example.toString())).kind());assertTrue(example.get("items").get(0).get("version_changed").isNull());assertEquals(GenerationRequestBuilderTest.build(root,stage),new String(CanonicalJson.bytes(req),StandardCharsets.UTF_8));}}
    @Test void KnownFalseAndUnknownOriginalEvidenceSurviveFormattingWithoutInventedNegativeJudgment(){for(Boolean changed:Arrays.asList(false,null)){var root=snapshot(Stage.AGENT_DEDUP,changed);var req=request(root,Stage.AGENT_DEDUP);var view=CanonicalJson.parse(req.get("messages").get(1).get("content").asText());assertArrayEquals(CanonicalJson.bytes(root),CanonicalJson.bytes(view));var quals=view.get(FrozenApplicationContext.FIELD).get("catalog_version_qualifications");if(changed==null)assertEquals(0,quals.size());else assertFalse(quals.get(0).get("version_changed").booleanValue());assertEquals(0,view.get(FrozenApplicationContext.FIELD).get("version_eligible_item_ids").size());}}
    @Test void AllHundredOriginalBodiesAndVersionReferencesRemainInTheFrozenMessage(){var root=snapshot(Stage.MODEL_DEDUP,null);var ctx=(ObjectNode)root.get(FrozenApplicationContext.FIELD);ctx.putArray("eligible_high_value_item_ids");var ids=ctx.putArray("item_ids");var candidates=ctx.putArray("candidates_by_item");var members=root.putArray("members");for(int n=0;n<100;n++){String id="fictional-item-"+n;ids.add(id);candidates.addObject().put("item_id",id).putArray("entity_ids").add("fictional-entity");members.addObject().put("id",id).putObject("body").put("text","Fictional complete original body "+n);}var req=request(root,Stage.MODEL_DEDUP);var view=CanonicalJson.parse(req.get("messages").get(1).get("content").asText());assertArrayEquals(CanonicalJson.bytes(root),CanonicalJson.bytes(view));assertEquals(100,view.get("members").size());assertEquals("Fictional complete original body 99",view.get("members").get(99).get("body").get("text").asText());}
    @Test void OriginalBudgetAndMalformedInputAreRejectedWithoutTruncationOrVersionFallback(){var builder=new GenerationRequestBuilder();var root=snapshot(Stage.AGENT_DEDUP,true);root.put("fictional_long","\"".repeat(300000));assertTrue(builder.buildWithinBudget(Stage.AGENT_DEDUP,root.toString(),CanonicalJson.hash(CanonicalJson.Domain.INPUT,root)).isEmpty());var large=root;assertThrows(GenerationFlowService.InputRejected.class,()->builder.build(Stage.AGENT_DEDUP,large.toString(),CanonicalJson.hash(CanonicalJson.Domain.INPUT,large)));root=snapshot(Stage.AGENT_DEDUP,true);var good=root;assertThrows(GenerationFlowService.InputRejected.class,()->builder.build(Stage.AGENT_DEDUP,good.toString(),"d".repeat(64)));assertThrows(GenerationFlowService.InputRejected.class,()->GenerationRequestBuilderTest.build(good,Stage.NEWS_DEDUP));((ObjectNode)good.get(FrozenApplicationContext.FIELD).get("catalog_version_qualifications").get(0).get("new_evidence_ref")).put("proof_hash","invalid");assertThrows(GenerationFlowService.InputRejected.class,()->GenerationRequestBuilderTest.build(good,Stage.AGENT_DEDUP));}
    @Test void ActualLoopbackTransportUsesFrozenMessagesAndOriginalV2ResultConstraintsOnce()throws Exception{var root=snapshot(Stage.SKILL_DEDUP,true);String frozen=GenerationRequestBuilderTest.build(root,Stage.SKILL_DEDUP);var req=CanonicalJson.parse(frozen);var received=new java.util.concurrent.atomic.AtomicReference<String>();var sends=new java.util.concurrent.atomic.AtomicInteger();var server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("localhost",0),0);var payload=new CatalogDedupResultV2Test().payload(Stage.SKILL_DEDUP,true);server.createContext("/chat/completions",exchange->{sends.incrementAndGet();received.set(new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));var response=JsonMapper.shared().createObjectNode().put("id","fictional-response").put("model","deepseek-flash");var choice=response.putArray("choices").addObject().put("finish_reason","stop");choice.putObject("message").put("content",payload.toString());byte[] bytes=response.toString().getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);exchange.close();});server.start();try{var client=com.lianxibu.site.repository.jobs.DeepSeekLoopbackFixture.client(java.net.http.HttpClient.newHttpClient(),java.net.URI.create("http://localhost:"+server.getAddress().getPort()+"/chat/completions"));root.put("fictional_later","caller changed after freezing");var outcome=client.sendOnce(frozen);assertEquals(com.lianxibu.site.repository.jobs.DeepSeekChatClient.Status.VALID,outcome.status());assertEquals(1,sends.get());var wire=CanonicalJson.parse(received.get());assertEquals(req.get("messages"),wire.get("messages"));assertFalse(wire.has("input_hash"));assertFalse(wire.has("json_schema"));var context=FrozenApplicationContext.fromJson(CanonicalJson.parse(req.get("messages").get(1).get("content").asText()).get(FrozenApplicationContext.FIELD));var input=context.input("fictional-root","fictional-attempt",req.get("input_hash").asText(),0);assertEquals("dedup",ResultApplicationService.validate(input,ResultApplicationService.providerEnvelope(input,outcome.contentJson())).kind());}finally{server.stop(0);}}
}
